CREATE TABLE autores (id_autor INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,nombre VARCHAR(120) NOT NULL,nacionalidad VARCHAR(60));
CREATE TABLE libros (id_libro INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,titulo VARCHAR(180) NOT NULL,isbn VARCHAR(20) NOT NULL UNIQUE,anio_publicacion INTEGER NOT NULL,categoria VARCHAR(80) NOT NULL,editorial VARCHAR(100),numero_paginas INTEGER NOT NULL CHECK(numero_paginas>0),precio NUMERIC(8,2) NOT NULL CHECK(precio>=0),disponible BOOLEAN NOT NULL DEFAULT TRUE,id_autor INTEGER NOT NULL REFERENCES autores(id_autor));
CREATE TABLE usuarios (id_usuario INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,nombre VARCHAR(120) NOT NULL,tipo_usuario VARCHAR(30) NOT NULL,carrera VARCHAR(100),activo BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE prestamos (id_prestamo INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,id_libro INTEGER NOT NULL REFERENCES libros(id_libro),id_usuario INTEGER NOT NULL REFERENCES usuarios(id_usuario),fecha_prestamo DATE NOT NULL,fecha_devolucion DATE NOT NULL,fecha_devolucion_real DATE,CHECK(fecha_devolucion>=fecha_prestamo),CHECK(fecha_devolucion_real IS NULL OR fecha_devolucion_real>=fecha_prestamo));
